const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('/workspace/testbed/docs/travel_summary.docx');

// docx is a ZIP file; parse ZIP manually
// Local file header signature = 0x04034b50
let offset = 0;
const files = {};
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig === 0x04034b50) {
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const name = buf.slice(offset + 30, offset + 30 + nameLen).toString('utf8');
    const dataStart = offset + 30 + nameLen + extraLen;
    const rawData = buf.slice(dataStart, dataStart + compSize);
    if (name === 'word/document.xml') {
      let data;
      if (compMethod === 8) {
        data = zlib.inflateRawSync(rawData).toString('utf8');
      } else {
        data = rawData.toString('utf8');
      }
      const texts = [...data.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)].map(m => m[1]);
      console.log(texts.join(' '));
    }
    offset = dataStart + compSize;
  } else {
    break;
  }
}
